function serializeSkillMarkdown(spec: CuratedSkillSpec): string {
  const esc = (s: string) => JSON.stringify(s);
  return `---\nname: ${spec.slug}\ndescription: ${esc(spec.description)}\nexample-prompt: ${esc(spec.examplePrompt)}\n---\n\n${spec.instructions.trim()}\n`;
}

const BUNDLE_CACHE = new Map<string, { bytes: Uint8Array; sha256: string }>();

export function buildCuratedSkillBundle(skillIdOrSlug: string): {
  spec: CuratedSkillSpec;
  bytes: Uint8Array;
  sha256: string;
} | null {
  const spec = CURATED_SKILL_SPECS.find((s) => s.id === skillIdOrSlug || s.slug === skillIdOrSlug);
  if (!spec) return null;
  let cached = BUNDLE_CACHE.get(spec.id);
  if (!cached) {
    const mdBytes = new TextEncoder().encode(serializeSkillMarkdown(spec));
    const zipped = zipSync({
      [`${spec.slug}/SKILL.md`]: mdBytes,
    });
    const sha256 = createHash("sha256").update(zipped).digest("hex");
    cached = { bytes: zipped, sha256 };
    BUNDLE_CACHE.set(spec.id, cached);
  }
  return { spec, ...cached };
}

export function isCuratedSkillId(skillId: string): boolean {
  return CURATED_SKILL_SPECS.some((s) => s.id === skillId);
}

export function getCuratedSkillDetail(skillIdOrSlug: string): MarketplaceSkillDetail | null {
  const built = buildCuratedSkillBundle(skillIdOrSlug);
  if (!built) return null;
  const { spec, sha256 } = built;
  return {
    id: spec.id,
    slug: spec.slug,
    name: spec.name,
    description: spec.description,
    category: spec.category,
    creatorName: spec.creatorName,
    version: 1,
    versionId: `${spec.id}-v1`,
    installs: spec.installs,
    featured: spec.featured,
    verified: spec.verified,
    iconUrl: null,
    updatedAt: spec.updatedAt,
    bundleSha256: sha256,
    files: ["SKILL.md"],
    instructions: spec.instructions,
    examplePrompt: spec.examplePrompt,
  };
}

export function listCuratedSkills(
  query: MarketplaceSkillQuery = {},
  extraLocalDetails: readonly MarketplaceSkillDetail[] = [],
): MarketplaceSkillPage {
  const q = (query.query ?? "").trim().toLowerCase();
  const curatedSummaries: MarketplaceSkillSummary[] = CURATED_SKILL_SPECS.map((spec) => ({
    id: spec.id,
    slug: spec.slug,
    name: spec.name,
    description: spec.description,
    category: spec.category,
    creatorName: spec.creatorName,
    version: 1,
    installs: spec.installs,
    featured: spec.featured,
    verified: spec.verified,
    iconUrl: null,
    updatedAt: spec.updatedAt,
  }));

  const localSummaries: MarketplaceSkillSummary[] = extraLocalDetails.map((d) => ({
    id: d.id,
    slug: d.slug,
    name: d.name,
    description: d.description,
    category: d.category,
    creatorName: d.creatorName === "Local" ? "本地上传技能" : d.creatorName,
    version: d.version,
    installs: d.installs,
    featured: d.featured,
    verified: d.verified,
    iconUrl: d.iconUrl,
    updatedAt: d.updatedAt,
  }));

  const seenIds = new Set<string>();
  const combined = [...localSummaries, ...curatedSummaries].filter((item) => {
    if (seenIds.has(item.id)) return false;
    seenIds.add(item.id);
    if (query.category && item.category !== query.category) return false;
    if (query.featured === true && !item.featured) return false;
    if (query.verified !== undefined && Boolean(item.verified) !== query.verified) return false;
    if (q) {
      const hay = `${item.name} ${item.slug} ${item.description} ${item.creatorName}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  const sortMode = query.sort ?? "installs";
  combined.sort((a, b) => {
    if (sortMode === "name") return a.name.localeCompare(b.name, "zh-CN");
    if (sortMode === "updated") return b.updatedAt.localeCompare(a.updatedAt);
    return b.installs - a.installs || a.name.localeCompare(b.name, "zh-CN");
  });

  const limit = query.limit && query.limit > 0 ? query.limit : combined.length;
  return {
    skills: combined.slice(0, limit),
    nextCursor: null,
  };
}
